using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _svc;

        public NotificationServiceTests()
        {
            _svc = new NotificationService();
            // Drain the static queue
            while (_svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _svc.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            _svc.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE, "TestUser");

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Course 'Test Course' has been created", notification.Message);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _svc.SendNotification("Student", "42", null, EntityOperation.CREATE, "TestUser");

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 42) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_Update_GeneratesUpdateMessage()
        {
            _svc.SendNotification("Course", "1", "Test Course", EntityOperation.UPDATE, "TestUser");

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_Delete_GeneratesDeleteMessage()
        {
            _svc.SendNotification("Course", "1", "Test Course", EntityOperation.DELETE, "TestUser");

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_TwoParamOverload_WorksCorrectly()
        {
            _svc.SendNotification("Student", "99", EntityOperation.CREATE, "TestUser");

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("(ID: ", notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultUserName_IsSystem()
        {
            _svc.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE);

            var notification = _svc.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var notification = _svc.ReceiveNotification();

            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_WithItems_DequeuesInOrder()
        {
            _svc.SendNotification("Course", "1", "First", EntityOperation.CREATE, "TestUser");
            _svc.SendNotification("Course", "2", "Second", EntityOperation.CREATE, "TestUser");
            _svc.SendNotification("Course", "3", "Third", EntityOperation.CREATE, "TestUser");

            var first = _svc.ReceiveNotification();
            var second = _svc.ReceiveNotification();
            var third = _svc.ReceiveNotification();

            Assert.Equal("1", first.EntityId);
            Assert.Equal("2", second.EntityId);
            Assert.Equal("3", third.EntityId);
        }

        [Fact]
        public void ReceiveNotification_AfterAllDequeued_ReturnsNull()
        {
            _svc.SendNotification("Course", "1", "Test", EntityOperation.CREATE, "TestUser");

            var notification = _svc.ReceiveNotification();
            Assert.NotNull(notification);

            var next = _svc.ReceiveNotification();
            Assert.Null(next);
        }

        [Fact]
        public void MaxQueueLength_Enforced_OldItemsRemoved()
        {
            for (int i = 0; i < 505; i++)
            {
                _svc.SendNotification("Item", i.ToString(), EntityOperation.CREATE, "TestUser");
            }

            int count = 0;
            while (_svc.ReceiveNotification() != null)
            {
                count++;
            }

            Assert.True(count <= 500, $"Expected at most 500 items but got {count}");
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _svc.MarkAsRead(1));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            using var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }
    }
}

