using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        private Student CreateStudent(string lastName, string firstName, DateTime enrollmentDate)
        {
            return new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = enrollmentDate
            };
        }

        // ── Index ──

        [Fact]
        public void Index_NoParams_ReturnsViewWithPaginatedStudents()
        {
            using var context = TestHelpers.CreateContext();
            context.Students.AddRange(
                CreateStudent("Alpha", "A", DateTime.Today),
                CreateStudent("Beta", "B", DateTime.Today),
                CreateStudent("Gamma", "C", DateTime.Today));
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            using var context = TestHelpers.CreateContext();
            context.Students.AddRange(
                CreateStudent("Smith", "John", DateTime.Today),
                CreateStudent("Jones", "Jane", DateTime.Today));
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Index(null, null, "Smith", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
        }

        [Fact]
        public void Index_SortByNameDesc_ReturnsSortedDescending()
        {
            using var context = TestHelpers.CreateContext();
            context.Students.AddRange(
                CreateStudent("Alpha", "A", DateTime.Today),
                CreateStudent("Charlie", "C", DateTime.Today),
                CreateStudent("Beta", "B", DateTime.Today));
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Index("name_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Charlie", model[0].LastName);
        }

        [Fact]
        public void Index_SortByDate_ReturnsSortedByDate()
        {
            using var context = TestHelpers.CreateContext();
            context.Students.AddRange(
                CreateStudent("A", "A", new DateTime(2023, 3, 1)),
                CreateStudent("B", "B", new DateTime(2023, 1, 1)),
                CreateStudent("C", "C", new DateTime(2023, 2, 1)));
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Index("Date", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(new DateTime(2023, 1, 1), model[0].EnrollmentDate);
            Assert.Equal(new DateTime(2023, 2, 1), model[1].EnrollmentDate);
            Assert.Equal(new DateTime(2023, 3, 1), model[2].EnrollmentDate);
        }

        [Fact]
        public void Index_SortByDateDesc_ReturnsSortedByDateDescending()
        {
            using var context = TestHelpers.CreateContext();
            context.Students.AddRange(
                CreateStudent("A", "A", new DateTime(2023, 1, 1)),
                CreateStudent("B", "B", new DateTime(2023, 3, 1)),
                CreateStudent("C", "C", new DateTime(2023, 2, 1)));
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Index("date_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(new DateTime(2023, 3, 1), model[0].EnrollmentDate);
            Assert.Equal(new DateTime(2023, 2, 1), model[1].EnrollmentDate);
            Assert.Equal(new DateTime(2023, 1, 1), model[2].EnrollmentDate);
        }

        [Fact]
        public void Index_SearchString_ResetsPageTo1()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            controller.Index(null, null, "Test", null);

            Assert.Equal("Test", controller.ViewBag.CurrentFilter);
        }

        [Fact]
        public void Index_NullSearchString_UseCurrentFilter()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            controller.Index(null, "Test", null, null);

            Assert.Equal("Test", controller.ViewBag.CurrentFilter);
        }

        // ── Details ──

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            using var context = TestHelpers.CreateContext();
            var student = CreateStudent("Smith", "John", DateTime.Today);
            context.Students.Add(student);
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Details(student.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("Smith", model.LastName);
        }

        [Fact]
        public void Details_InvalidId_ThrowsInvalidOperationException()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            Assert.Throws<InvalidOperationException>(() => controller.Details(999));
        }

        // ── Create GET ──

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // ── Create POST ──

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);
            var student = CreateStudent("Smith", "John", DateTime.Today);

            var result = controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_ValidStudent_SavesStudent()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);
            var student = CreateStudent("Smith", "John", DateTime.Today);

            controller.Create(student);

            Assert.Equal(1, context.Students.Count());
        }

        [Fact]
        public void Create_Post_InvalidEnrollmentDate_ReturnsViewWithModelError()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);
            var student = CreateStudent("Smith", "John", DateTime.MinValue);

            var result = controller.Create(student);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        // ── Edit GET ──

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            using var context = TestHelpers.CreateContext();
            var student = CreateStudent("Smith", "John", DateTime.Today);
            context.Students.Add(student);
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Edit(student.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("Smith", model.LastName);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        // ── Edit POST ──

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var dbName = Guid.NewGuid().ToString();

            using (var setupContext = TestHelpers.CreateContext(dbName))
            {
                setupContext.Students.Add(CreateStudent("Smith", "John", DateTime.Today));
                setupContext.SaveChanges();
            }

            using var context = TestHelpers.CreateContext(dbName);
            var controller = new StudentsController(context);
            var studentToEdit = context.Students.First();
            context.Entry(studentToEdit).State = EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = studentToEdit.ID,
                LastName = "Updated",
                FirstMidName = "John",
                EnrollmentDate = DateTime.Today
            };

            var result = controller.Edit(updatedStudent);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidEnrollmentDate_ReturnsView()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);
            var student = CreateStudent("Smith", "John", DateTime.MinValue);

            var result = controller.Edit(student);

            Assert.IsType<ViewResult>(result);
            Assert.False(controller.ModelState.IsValid);
        }

        // ── Delete GET ──

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            using var context = TestHelpers.CreateContext();
            var student = CreateStudent("Smith", "John", DateTime.Today);
            context.Students.Add(student);
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.Delete(student.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("Smith", model.LastName);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new StudentsController(context);

            var result = controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        // ── Delete POST ──

        [Fact]
        public void DeleteConfirmed_ValidId_DeletesStudentAndRedirects()
        {
            using var context = TestHelpers.CreateContext();
            var student = CreateStudent("Smith", "John", DateTime.Today);
            context.Students.Add(student);
            context.SaveChanges();

            var controller = new StudentsController(context);
            var result = controller.DeleteConfirmed(student.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(0, context.Students.Count());
        }
    }
}

