    public class HomeControllerTests
    {
        [Fact]
        public void Index_ReturnsView()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new HomeController(context);

            var result = controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentGroups()
        {
            using var context = TestHelpers.CreateContext();
            var sharedDate = new DateTime(2023, 9, 1);
            var differentDate = new DateTime(2024, 1, 15);
            context.Students.AddRange(
                new Student { LastName = "A", FirstMidName = "A", EnrollmentDate = sharedDate },
                new Student { LastName = "B", FirstMidName = "B", EnrollmentDate = sharedDate },
                new Student { LastName = "C", FirstMidName = "C", EnrollmentDate = differentDate });
            context.SaveChanges();

            var controller = new HomeController(context);
            var result = controller.About();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(2, model.Count);

            var sharedGroup = model.First(g => g.EnrollmentDate == sharedDate);
            Assert.Equal(2, sharedGroup.StudentCount);
        }

        [Fact]
        public void About_NoStudents_ReturnsEmptyList()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new HomeController(context);

            var result = controller.About();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new HomeController(context);

            var result = controller.Contact();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("Your contact page.", viewResult.ViewData["Message"]);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new HomeController(context);

            var result = controller.Error();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithMessage()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new HomeController(context);

            var result = controller.Unauthorized();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("You don't have permission to access this resource.", viewResult.ViewData["Message"]);
        }
    }
}

using System;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests
    {
        public NotificationsControllerTests()
        {
            // Drain the static notification queue before each test
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsEmptyList()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new NotificationsController(context);

            var jsonResult = controller.GetNotifications();
            var value = jsonResult.Value;

            var success = (bool)value.GetType().GetProperty("success").GetValue(value);
            var count = (int)value.GetType().GetProperty("count").GetValue(value);

            Assert.True(success);
            Assert.Equal(0, count);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new NotificationsController(context);

            var svc = new NotificationService();
            svc.SendNotification("Test", "1", EntityOperation.CREATE, "User");
            svc.SendNotification("Test", "2", EntityOperation.UPDATE, "User");
            svc.SendNotification("Test", "3", EntityOperation.DELETE, "User");

            var jsonResult = controller.GetNotifications();
            var value = jsonResult.Value;

            var success = (bool)value.GetType().GetProperty("success").GetValue(value);
            var count = (int)value.GetType().GetProperty("count").GetValue(value);

            Assert.True(success);
            Assert.Equal(3, count);
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new NotificationsController(context);

            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "User");
            }

            var jsonResult = controller.GetNotifications();
            var value = jsonResult.Value;

            var success = (bool)value.GetType().GetProperty("success").GetValue(value);
            var count = (int)value.GetType().GetProperty("count").GetValue(value);

            Assert.True(success);
            Assert.Equal(10, count);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new NotificationsController(context);

            var jsonResult = controller.MarkAsRead(1);
            var value = jsonResult.Value;

            var success = (bool)value.GetType().GetProperty("success").GetValue(value);
            Assert.True(success);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            using var context = TestHelpers.CreateContext();
            var controller = new NotificationsController(context);

            var result = controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

